import { fileURLToPath } from "node:url"
import type { Plugin } from "vite"
import { defineConfig } from "vitest/config"

// `virtual:mercur/*` modules are generated by the @mercurjs/dashboard-sdk Vite
// plugin when a host app (apps/vendor) builds the panel. The package's own
// test run has no host app, so source files that reach them (e.g. the shared
// `i18n` singleton imported by products/create/utils.ts) failed with
// "Cannot find package 'virtual:mercur/i18n'". Resolve them to what the SDK
// emits for a host with no extensions: no custom i18n resources, empty config.
const MERCUR_VIRTUAL_MODULES: ReadonlyArray<string> = [
  "virtual:mercur/i18n",
  "virtual:mercur/config",
]

const RESOLVED_PREFIX = "\0"

const mercurVirtualModulesForTests = (): Plugin => ({
  name: "kayi:mercur-virtual-modules-for-tests",
  enforce: "pre",
  resolveId(id: string): string | null {
    return MERCUR_VIRTUAL_MODULES.includes(id) ? RESOLVED_PREFIX + id : null
  },
  load(id: string): string | null {
    return id.startsWith(RESOLVED_PREFIX) &&
      MERCUR_VIRTUAL_MODULES.includes(id.slice(RESOLVED_PREFIX.length))
      ? "export default {}"
      : null
  },
})

const fromSrc = (dir: string): string =>
  fileURLToPath(new URL(`./src/${dir}`, import.meta.url))

export default defineConfig({
  plugins: [mercurVirtualModulesForTests()],
  // Mirrors tsconfig.json "paths" so sources using the @lib/* style aliases
  // resolve under vitest the same way they do under tsc and tsup.
  resolve: {
    alias: {
      "@components": fromSrc("components"),
      "@hooks": fromSrc("hooks"),
      "@lib": fromSrc("lib"),
      "@pages": fromSrc("pages"),
      "@providers": fromSrc("providers"),
      "@assets": fromSrc("assets"),
      "@/": fromSrc(""),
    },
  },
  test: {
    environment: "node",
  },
})
